package com.nextaicommerce.platform.fba;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import java.util.*;import java.time.*;import java.math.*;
import com.nextaicommerce.platform.catalog.CatalogRepository;import com.nextaicommerce.platform.orders.PackingPackageNames;
import org.springframework.jdbc.core.JdbcTemplate;import tools.jackson.databind.ObjectMapper;
import static com.nextaicommerce.platform.fba.FbaInboundWorkflow.*;import static com.nextaicommerce.platform.fba.FbaInboundAdapter.Operation.*;
class FbaInboundPayloadsTest {
 final UUID tenant=UUID.randomUUID(),store=UUID.randomUUID(),planId=UUID.randomUUID(),warehouse=UUID.randomUUID(),item=UUID.randomUUID();final Scope scope=new Scope(tenant,tenant,store,planId);final ObjectMapper json=new ObjectMapper();
 final FbaReplenishmentPlans plans=mock(FbaReplenishmentPlans.class);final JdbcTemplate jdbc=mock(JdbcTemplate.class);final CatalogRepository catalog=mock(CatalogRepository.class);final PackingPackageNames packages=mock(PackingPackageNames.class);
 FbaInboundPayloads payloads;FbaReplenishmentPlans.Plan plan;
 FbaPackingManifest.Carton carton(boolean confirmed){return new FbaPackingManifest.Carton(UUID.randomUUID(),warehouse,"02.Pak",new BigDecimal("12"),new BigDecimal("10"),new BigDecimal("2"),"in",new BigDecimal("32"),"oz",confirmed,Map.of("SKU",2));}
 Map<String,Object> allocation(UUID product,int ratio,int quantity){return Map.of("warehouse_id",warehouse,"seller_sku","SKU","account_catalog_item_id",product,"each_per_sku",ratio,"quantity",quantity,"dispatched",0,"reservation_status","ACTIVE");}
 FbaReplenishmentPlans.Plan makePlan(Map<String,Object> packing,List<Map<String,Object>> allocations){return new FbaReplenishmentPlans.Plan(planId,"FBA Local", "ALLOCATED",1,3,Map.of("packing",withPreparation(packing)),allocations,List.of());}
 Map<String,Object> withPreparation(Map<String,Object> packing){var copy=new HashMap<String,Object>(packing);copy.put("preparationByOrigin",Map.of(warehouse.toString(),Map.of("SKU",new FbaReplenishmentPlans.Preparation("SELLER","SELLER",true))));return copy;}
 @BeforeEach void setup(){payloads=spy(new FbaInboundPayloads(plans,jdbc,catalog,packages,json));doNothing().when(payloads).requireLeadTimes(eq(scope),anySet());plan=makePlan(Map.of("validated",true,"cartons",List.of(carton(true))),List.of(allocation(item,4,8)));when(plans.get(tenant,store,planId)).thenAnswer(i->plan);when(packages.names(tenant)).thenReturn(List.of("02.Pak"));doReturn(Map.of()).when(payloads).sourceExpirations(eq(scope),eq(warehouse),anySet());when(catalog.warehouseDetails(tenant,warehouse)).thenReturn(new CatalogRepository.WarehouseDetails(warehouse,"Managed Warehouse",false,"123 Real Street",null,"Tomball","TX","77377","US",List.of(new CatalogRepository.WarehouseContact("Warehouse Contact","2815550100")),"ACTIVE"));when(jdbc.queryForObject(contains("SELECT marketplace_identifier"),eq(String.class),eq(tenant),eq(store))).thenReturn("ATVPDKIKX0DER");}
 FbaInboundOrchestration.Command command(FbaInboundAdapter.Operation operation,String child,String option){return new FbaInboundOrchestration.Command(UUID.randomUUID(),1,operation,child,option,false);}
 FbaInboundOrchestration.Checkpoint state(FbaInboundAdapter.Operation operation,String option,String source){UUID request=UUID.randomUUID();var attempt=new Attempt(request,operation,null,1,option,Status.SUCCEEDED,"op-confirmed");var origin=new Origin(scope,warehouse,1,"remote-plan",Map.of(request,attempt),Map.of("child",new Child("child",Map.of("SKU",2))),Map.of(),List.of());return new FbaInboundOrchestration.Checkpoint(origin,Map.of(),Map.of(option,new FbaInboundOrchestration.Option(option,operation,1,Instant.now().plusSeconds(3600),BigDecimal.ZERO,"USD",List.of("child"),null,source)));}
 @Test void createUsesPersistedAllocationAndManagedWarehouse(){var result=json.readTree(payloads.build(scope,warehouse,FbaInboundOrchestration.Checkpoint.initial(scope,warehouse),command(CREATE,null,null)));assertEquals(2,result.path("items").get(0).path("quantity").asInt());assertEquals("SELLER",result.path("items").get(0).path("labelOwner").asText());assertEquals("SELLER",result.path("items").get(0).path("prepOwner").asText());assertEquals("123 Real Street",result.path("sourceAddress").path("addressLine1").asText());assertEquals("ATVPDKIKX0DER",result.path("destinationMarketplaces").get(0).asText());}
 @Test void bundleComponentsDoNotMultiplySkuQuantity(){plan=makePlan(Map.of("validated",true,"cartons",List.of(carton(true))),List.of(allocation(item,4,8),allocation(UUID.randomUUID(),2,4)));assertEquals(Map.of("SKU",2),payloads.expectedSkuUnits(scope,warehouse));}
 @Test void unconfirmedCartonsBlockBeforePayload(){plan=makePlan(Map.of("validated",true,"cartons",List.of(carton(false))),plan.allocations());assertThrows(IllegalArgumentException.class,()->payloads.build(scope,warehouse,FbaInboundOrchestration.Checkpoint.initial(scope,warehouse),command(CREATE,null,null)));}
 @Test void anotherAccountCannotBuildFromThisPlan(){var other=new Scope(tenant,UUID.randomUUID(),store,planId);assertThrows(IllegalArgumentException.class,()->payloads.expectedSkuUnits(other,warehouse));}
 @Test void missingManagedContactIsNotInvented(){when(catalog.warehouseDetails(tenant,warehouse)).thenReturn(new CatalogRepository.WarehouseDetails(warehouse,"Warehouse",false,"Street",null,"City","TX","77377","US",List.of(),"ACTIVE"));assertThrows(IllegalStateException.class,()->payloads.build(scope,warehouse,FbaInboundOrchestration.Checkpoint.initial(scope,warehouse),command(CREATE,null,null)));}
 @Test void packingPreservesActualDimensionsAndConvertsOuncesToPounds(){var state=state(CONFIRM_PACKING,"packing","{\"packingGroups\":[\"pg1234abcd-1234-abcd-5678-1234abcd5678\"]}");var body=json.readTree(payloads.build(scope,warehouse,state,command(PACKING_INFORMATION,null,null)));var box=body.path("packageGroupings").get(0).path("boxes").get(0);assertEquals(12,box.path("dimensions").path("length").asInt());assertEquals("IN",box.path("dimensions").path("unitOfMeasurement").asText());assertEquals("LB",box.path("weight").path("unit").asText());assertEquals(2,box.path("weight").path("value").asDouble());assertEquals(1,box.path("quantity").asInt());}
 @Test void multipleGroupsRequireVerifiedMembership(){var state=state(CONFIRM_PACKING,"packing","{\"packingGroups\":[\"group-A\",\"group-B\"]}");assertThrows(IllegalStateException.class,()->payloads.build(scope,warehouse,state,command(PACKING_INFORMATION,null,null)));}
 @Test void missingReadyToShipDateBlocksRatherThanUsingToday(){var state=state(CONFIRM_PLACEMENT,"placement","{}");assertThrows(IllegalStateException.class,()->payloads.build(scope,warehouse,state,command(TRANSPORT_OPTIONS,null,null)));}
 @Test void transportUsesSavedActualReadyTimeAndVerifiedChildren(){Instant ready=Instant.now().plusSeconds(7200).truncatedTo(java.time.temporal.ChronoUnit.MINUTES);plan=makePlan(Map.of("validated",true,"cartons",List.of(carton(true)),"transportByOrigin",Map.of(warehouse.toString(),Map.of("readyToShipAt",ready.toString()))),plan.allocations());var state=state(CONFIRM_PLACEMENT,"placement","{}");var result=json.readTree(payloads.build(scope,warehouse,state,command(TRANSPORT_OPTIONS,null,null)));assertEquals("placement",result.path("placementOptionId").asText());assertEquals("child",result.path("shipmentTransportationConfigurations").get(0).path("shipmentId").asText());assertEquals(ready.toString(),result.path("shipmentTransportationConfigurations").get(0).path("readyToShipWindow").path("start").asText());}
 @Test void cancellationDoesNotRequirePackingOrAnActiveAllocation(){plan=new FbaReplenishmentPlans.Plan(planId,"FBA Cancel","CANCELLED",2,1,Map.of(),List.of(),List.of());assertEquals("{}",payloads.build(scope,warehouse,FbaInboundOrchestration.Checkpoint.initial(scope,warehouse),command(CANCEL,null,null)));}
 @Test void createRequiresConfirmedActualExpirationAndDoesNotInventOne(){doReturn(Map.of("SKU",LocalDate.of(2027,1,1))).when(payloads).sourceExpirations(eq(scope),eq(warehouse),anySet());assertThrows(IllegalStateException.class,()->payloads.build(scope,warehouse,FbaInboundOrchestration.Checkpoint.initial(scope,warehouse),command(CREATE,null,null)));}
 @Test void createUsesExactConfirmedSourceExpiration(){LocalDate date=LocalDate.of(2027,1,1);doReturn(Map.of("SKU",date)).when(payloads).sourceExpirations(eq(scope),eq(warehouse),anySet());var old=carton(true);var carton=new FbaPackingManifest.Carton(old.id(),warehouse,old.packageName(),old.length(),old.width(),old.height(),old.dimensionUnit(),old.weight(),old.weightUnit(),true,old.contents(),Map.of("SKU",date));plan=makePlan(Map.of("validated",true,"cartons",List.of(carton)),plan.allocations());var body=json.readTree(payloads.build(scope,warehouse,FbaInboundOrchestration.Checkpoint.initial(scope,warehouse),command(CREATE,null,null)));assertEquals(date.toString(),body.path("items").get(0).path("expiration").asText());}
 @Test void missingPreparationCannotSilentlyDefaultToSeller(){var packing=Map.<String,Object>of("validated",true,"cartons",List.of(carton(true)));plan=new FbaReplenishmentPlans.Plan(planId,"FBA Local","ALLOCATED",1,3,Map.of("packing",packing),plan.allocations(),List.of());assertThrows(IllegalStateException.class,()->payloads.build(scope,warehouse,FbaInboundOrchestration.Checkpoint.initial(scope,warehouse),command(CREATE,null,null)));}
 @Test void explicitPreparationOwnersAreUsedInCreate(){var packing=new HashMap<>(withPreparation(Map.of("validated",true,"cartons",List.of(carton(true)))));packing.put("preparationByOrigin",Map.of(warehouse.toString(),Map.of("SKU",new FbaReplenishmentPlans.Preparation("AMAZON","NONE",true))));plan=new FbaReplenishmentPlans.Plan(planId,"FBA Local","ALLOCATED",1,3,Map.of("packing",packing),plan.allocations(),List.of());var body=json.readTree(payloads.build(scope,warehouse,FbaInboundOrchestration.Checkpoint.initial(scope,warehouse),command(CREATE,null,null)));assertEquals("AMAZON",body.path("items").get(0).path("prepOwner").asText());assertEquals("NONE",body.path("items").get(0).path("labelOwner").asText());}
 @Test void unconfiguredLeadTimesBlockCreation(){doCallRealMethod().when(payloads).requireLeadTimes(eq(scope),anySet());assertThrows(IllegalStateException.class,()->payloads.build(scope,warehouse,FbaInboundOrchestration.Checkpoint.initial(scope,warehouse),command(CREATE,null,null)));}
}

